programs:
$offset = 0;
$limit = 12;
$articleList = [];
do {
    $listResult = $tools->call('cms_list_articles', ['offset' => $offset, 'limit' => $limit]);
    if (!isset($listResult->items) || !is_array($listResult->items)) {
        break;
    }
    foreach ($listResult->items as $item) {
        $articleList[] = $item; // item has id, title
    }
    $next = $listResult->next_offset ?? null;
    if ($next === null) {
        break;
    }
    $offset = $next;
} while (true);

// Fetch article metadata in batches of up to 12 ids
$articles = [];
$ids = array_map(fn($a) => $a->id, $articleList);
for ($i = 0; $i < count($ids); $i += 12) {
    $batch = array_slice($ids, $i, 12);
    $articleResult = $tools->call('cms_get_articles', ['ids' => $batch]);
    if (isset($articleResult->items) && is_array($articleResult->items)) {
        foreach ($articleResult->items as $art) {
            $articles[] = $art; // includes meta_description, image_id, title
        }
    }
}

// Collect unique image ids
$imageIds = [];
foreach ($articles as $art) {
    if (isset($art->image_id) && $art->image_id !== null) {
        $imageIds[$art->image_id] = true;
    }
}
$imageIds = array_keys($imageIds);
// Fetch media records in batches of up to 12
$mediaMap = [];
for ($i = 0; $i < count($imageIds); $i += 12) {
    $batch = array_slice($imageIds, $i, 12);
    $mediaResult = $tools->call('cms_get_media', ['ids' => $batch]);
    if (isset($mediaResult->items) && is_array($mediaResult->items)) {
        foreach ($mediaResult->items as $media) {
            $mediaMap[$media->id] = $media;
        }
    }
}

$findings = [];
foreach ($articles as $art) {
    $missingDesc = false;
    $missingAlt = false;
    if (!isset($art->meta_description) || trim($art->meta_description) === '') {
        $missingDesc = true;
    }
    $imgId = $art->image_id ?? null;
    if ($imgId !== null) {
        $media = $mediaMap[$imgId] ?? null;
        if ($media === null || !isset($media->alt) || trim($media->alt) === '') {
            $missingAlt = true;
        }
    } else {
        // No image_id means missing alt as well
        $missingAlt = true;
    }
    if ($missingDesc || $missingAlt) {
        $issues = [];
        if ($missingDesc) $issues['missing_description'] = true;
        if ($missingAlt) $issues['missing_alt'] = true;
        $findings[] = (object)[
            'id' => $art->id,
            'title' => $art->title,
            'issues' => $issues
        ];
    }
}
// Sort findings by id
usort($findings, fn($a, $b) => $a->id <=> $b->id);

$output = (object)[
    'audited' => count($articles),
    'findings' => $findings
];
return $output;

