$allIds = [];
$offset = 0;
$limit = 12;
do {
    $list = $tools->call('cms_list_articles', ['offset'=>$offset, 'limit'=>$limit]);
    if (!isset($list->items) || !is_array($list->items)) {
        break;
    }
    foreach ($list->items as $item) {
        $allIds[] = $item->id;
    }
    $next = $list->next_offset ?? null;
    if ($next === null) {
        $offset = null;
    } else {
        $offset = $next;
    }
} while ($offset !== null);

$missing = [];
$audited = 0;
for ($i = 0; $i < count($allIds); $i += 12) {
    $batch = array_slice($allIds, $i, 12);
    $articles = $tools->call('cms_get_articles', ['ids' => $batch]);
    if (!isset($articles->items) || !is_array($articles->items)) {
        continue;
    }
    foreach ($articles->items as $art) {
        $audited++;
        $desc = $art->meta_description ?? null;
        if ($desc === null || $desc === '') {
            $missing[] = $art->id;
        }
    }
}
sort($missing);
return ['audited' => $audited, 'missing' => $missing];

$allIds = [];
$offset = 0;
$limit = 12;
do {
    $list = $tools->call('cms_list_articles', ['offset'=>$offset, 'limit'=>$limit]);
    if (!isset($list->items) || !is_array($list->items)) {
        break;
    }
    foreach ($list->items as $item) {
        $allIds[] = $item->id;
    }
    $next = $list->next_offset ?? null;
    $offset = $next === null ? null : $next;
} while ($offset !== null);

$counts = ['en'=>0, 'nl'=>0, 'de'=>0];
for ($i = 0; $i < count($allIds); $i += 12) {
    $batch = array_slice($allIds, $i, 12);
    $articles = $tools->call('cms_get_articles', ['ids' => $batch]);
    if (!isset($articles->items) || !is_array($articles->items)) continue;
    foreach ($articles->items as $art) {
        $desc = $art->meta_description ?? null;
        if ($desc === null || $desc === '') {
            $lang = $art->language ?? '';
            if (isset($counts[$lang])) {
                $counts[$lang]++;
            }
        }
    }
}
return ['missingByLanguage' => $counts];

