$results = [];
$offset = 0;
$limit = 12;
$allArticles = [];
$total = 0;
do {
    $list = $tools->call('cms_list_articles', ['offset' => $offset, 'limit' => $limit]);
    if (!isset($list->items) || !is_array($list->items)) {
        break;
    }
    foreach ($list->items as $item) {
        $allArticles[] = $item; // expects id and title
    }
    $total = $list->total ?? count($allArticles);
    $next = $list->next_offset ?? null;
    if ($next === null) {
        $offset = null;
    } else {
        $offset = $next;
    }
} while ($offset !== null);

// Fetch article metadata in batches
$articleMap = [];
$articleCount = count($allArticles);
for ($i = 0; $i < $articleCount; $i += 12) {
    $batch = array_slice($allArticles, $i, 12);
    $ids = [];
    foreach ($batch as $a) {
        $ids[] = $a->id;
    }
    $articles = $tools->call('cms_get_articles', ['ids' => $ids]);
    if (isset($articles->items) && is_array($articles->items)) {
        foreach ($articles->items as $art) {
            $articleMap[$art->id] = $art; // includes meta_description, image_id, title
        }
    }
}

// Collect unique image ids
$imageIds = [];
foreach ($articleMap as $art) {
    if (isset($art->image_id) && $art->image_id !== null) {
        $imageIds[$art->image_id] = true;
    }
}
$imageIds = array_keys($imageIds);

// Fetch media metadata in batches
$mediaMap = [];
$imgCount = count($imageIds);
for ($i = 0; $i < $imgCount; $i += 12) {
    $batchIds = array_slice($imageIds, $i, 12);
    $media = $tools->call('cms_get_media', ['ids' => $batchIds]);
    if (isset($media->items) && is_array($media->items)) {
        foreach ($media->items as $m) {
            $mediaMap[$m->id] = $m; // includes alt
        }
    }
}

$findings = [];
foreach ($articleMap as $art) {
    $issues = [];
    // Check meta_description
    if (!isset($art->meta_description) || $art->meta_description === '' || $art->meta_description === null) {
        $issues[] = 'missing_description';
    }
    // Check alt of hero image
    $imgId = $art->image_id ?? null;
    if ($imgId !== null && isset($mediaMap[$imgId])) {
        $media = $mediaMap[$imgId];
        if (!isset($media->alt) || $media->alt === '' || $media->alt === null) {
            $issues[] = 'missing_alt';
        }
    } else {
        // If image missing or media not found, treat as missing alt as well
        $issues[] = 'missing_alt';
    }
    if (!empty($issues)) {
        $findings[] = [
            'id' => $art->id,
            'title' => $art->title,
            'issues' => $issues,
        ];
    }
}
// Sort findings by id
usort($findings, function($a, $b) { return $a['id'] <=> $b['id']; });

return ['audited' => $total, 'findings' => $findings];

